import sys


def main():
    tokens = sys.stdin.read().split()
    n, m = int(tokens[0]), int(tokens[1])
    grid = tokens[2:2 + n]
    open_cells = set()
    burning0 = set()
    for r in range(n):
        for c in range(m):
            if grid[r][c] != '#':
                open_cells.add((r, c))
            if grid[r][c] == 'F':
                burning0.add((r, c))
            if grid[r][c] == 'S':
                start = (r, c)
            if grid[r][c] == 'E':
                goal = (r, c)

    def around(cell):
        r, c = cell
        out = [cell]
        for nb in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
            if nb in open_cells:
                out.append(nb)
        return out

    def spread(burning):
        nxt = set(burning)
        for cell in burning:
            nxt.update(around(cell))
        return nxt

    def escapes(wait):
        burning = set(burning0)
        for _ in range(wait):
            burning = spread(burning)
        if start in burning:
            return False
        here = {start}
        for _ in range(2 * n * m + 5):
            if goal in here:
                return True
            burning = spread(burning)
            nxt = set()
            for cell in here:
                for nb in around(cell):
                    if nb not in burning:
                        nxt.add(nb)
            if not nxt:
                return False
            here = nxt
        return False

    cap = 2 * n * m
    if escapes(cap):
        print('INF')
        return
    best = -1
    for w in range(cap + 1):
        if escapes(w):
            best = w
    print(best)


main()
